mapper.insert:
/* SchoolInfoMapper.upsertSchoolBatch */ INSERT INTO school_info ( school_code, school_name, school_level, region, district, status, created_by, updated_by, created_at, updated_at ) VALUES
(#{item.schoolCode}, #{item.schoolName}, #{item.schoolLevel}, #{item.region}, #{item.district}, #{item.status}, #{item.createdBy}, #{item.updatedBy}, #{item.createdAt}, #{item.updatedAt})
ON DUPLICATE KEY UPDATE school_name = VALUES(school_name), school_level = VALUES(school_level), region = VALUES(region), district = VALUES(district), status = VALUES(status), updated_by = VALUES(updated_by), updated_at = VALUES(updated_at)

mapper.select:
/* SchoolInfoMapper.findSchoolsPaged */
SELECT school_code, school_name, school_level, region, district, status,
       created_by, updated_by, created_at, updated_at
FROM school_info


        AND (school_name LIKE CONCAT('%',#{keyword},'%') OR school_code LIKE CONCAT('%',#{keyword},'%'))


        AND school_level = #{schoolLevel}


        AND region LIKE CONCAT('%',#{region},'%')


ORDER BY school_name ASC
LIMIT #{limit} OFFSET #{offset}

/* SchoolInfoMapper.countSchoolsPaged */
SELECT COUNT(*)
FROM school_info


        AND (school_name LIKE CONCAT('%',#{keyword},'%') OR school_code LIKE CONCAT('%',#{keyword},'%'))


        AND school_level = #{schoolLevel}


        AND region LIKE CONCAT('%',#{region},'%')

/* SchoolInfoMapper.existsBySchoolCode */
SELECT COUNT(*) > 0
FROM school_info
WHERE school_code = #{schoolCode}
